#include "vibration/reference_library.hpp"
#include "vibration/sha256.hpp"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace vibration;
namespace {
void check(bool v,const char*s){if(!v)throw std::runtime_error(s);}
template<class F>void rejects(F f,const char*s){bool ok=false;try{f();}catch(const std::exception&){ok=true;}check(ok,s);}
std::string hash(const std::string&s){return sha256_hex(reinterpret_cast<const std::uint8_t*>(s.data()),s.size());}
// Mathematical post-extraction declarations test the fit API only. These
// identities/labels are fabricated and never enter the mechanical GUI library.
ReferenceSample sample(unsigned c,unsigned identity,unsigned count=1){
    const char*labels[]{"normal","imbalance","misalignment","looseness"};ReferenceSample s;s.path="mathematical-only-"+std::to_string(identity)+".BIN";s.label=labels[c];s.capture_sha256=hash(s.path);s.session_id="math-session-"+std::to_string(identity);s.operator_updated_at="fixture-only";
    for(unsigned i=0;i<count;++i){CandidateWindow w;w.setup_id="mathematical-setup";w.configuration="abcd1234";w.sample_rate_hz=5000;w.capture_sha256=s.capture_sha256;w.raw_window_sha256=hash(s.path+std::to_string(i));w.source_path=s.path;w.source="mathematical-feature-fixture";w.source_session_id=s.session_id;w.valid=true;w.first_index=10000*i;w.last_index=w.first_index+9999;w.rpm=w.rpm_min=w.rpm_max=1200;w.features.fill(std::pow(2.,c));s.windows.push_back(w);}return s;
}
}
int main(){try{
    // Freeze the original API/averaging/inference expectations against the
    // explicitly selected v1 policy; V2/V3 ensembles have their own tests.
    const auto fit_reference_model=[](const std::vector<ReferenceSample>& samples){return vibration::fit_reference_model(samples,ReferenceFitPolicy::LegacyNearest);};
    std::vector<ReferenceSample>s;for(unsigned c=0;c<4;++c)s.push_back(sample(c,c));const auto m=fit_reference_model(s);check(m.kind=="reference_exemplars"&&m.baseline_count==1,"four independent reference files suffice without pretending five windows are trials");for(unsigned c=0;c<4;++c){const auto p=infer_candidate(s[c].windows[0],m);check(p.classification==s[c].label&&!p.validated,"all four mathematical prototypes execute actual inference");}
    check(candidate_model_text(parse_candidate_model(candidate_model_text(m)))==candidate_model_text(m),"prototype, counts and provenance roundtrip");auto longer=s;longer[0]=sample(0,0,10);const auto balanced=fit_reference_model(longer);check(m.references.size()==balanced.references.size(),"ten stable-speed windows collapse to one file representative");for(unsigned j=0;j<36;++j)check(std::abs(m.references[0].features[j]-balanced.references[0].features[j])<1e-12,"long file does not receive extra exemplar votes");
    auto ambiguous=s[0].windows[0];ambiguous.features.fill(1.5);check(infer_candidate(ambiguous,m).classification=="unknown","inter-class ambiguity stays unknown");auto far=ambiguous;far.features.fill(1e5);check(infer_candidate(far,m).status=="rejected_unknown","out of reference distribution stays unknown");
    auto unavailable=s;unavailable.resize(3);rejects([&]{fit_reference_model(unavailable);},"all four classes mandatory");auto duplicate=s;duplicate.push_back(s[0]);rejects([&]{fit_reference_model(duplicate);},"duplicate path or content rejected");auto copied=s;copied[1].capture_sha256=s[0].capture_sha256;copied[1].windows[0].capture_sha256=copied[1].capture_sha256;rejects([&]{fit_reference_model(copied);},"byte-identical differently named copies rejected");auto session=s;session[1].session_id=session[0].session_id;rejects([&]{fit_reference_model(session);},"same acquisition SD segments rejected");
    auto mismatch=s;mismatch[2].windows[0].configuration="badb1234";rejects([&]{fit_reference_model(mismatch);},"configuration mismatch rejected");auto synthetic=s;synthetic[0].windows[0].synthetic=true;rejects([&]{fit_reference_model(synthetic);},"synthetic mechanical references rejected");auto invalid=s;invalid[0].windows[0].valid=false;rejects([&]{fit_reference_model(invalid);},"quality invalid reference rejected");auto preview=s;preview[0].windows[0].input_kind="local_full_raw_crc_continuous";rejects([&]{fit_reference_model(preview);},"preview never becomes a saved reference");
    auto multi=s;for(unsigned c=0;c<4;++c){auto extra=sample(c,c+4);for(auto&w:extra.windows){w.rpm=w.rpm_min=w.rpm_max=2000;for(double&x:w.features)x*=10;}multi.push_back(extra);}const auto multiple=fit_reference_model(multi);check(multiple.references.size()==8,"different operating points are retained without averaging");for(unsigned c=0;c<4;++c){check(infer_candidate(multi[c].windows[0],multiple).classification==multi[c].label,"low RPM class stays correct with high RPM references present");check(infer_candidate(multi[c+4].windows[0],multiple).classification==multi[c+4].label,"high RPM uses its own four-class feature neighborhood");}
    auto gap=multi[0].windows[0];gap.rpm=gap.rpm_min=gap.rpm_max=1600;check(infer_candidate(gap,multiple).status=="coverage_insufficient","unmeasured RPM gap inside model envelope is not interpolated");auto incomplete=multi;incomplete.pop_back();const auto partial=fit_reference_model(incomplete);check(infer_candidate(multi[4].windows[0],partial).status=="coverage_insufficient","one missing class at a supported RPM still prevents classification");auto wide=multi[4].windows[0];wide.rpm_min=1750;wide.rpm_max=2199;check(infer_candidate(wide,multiple).status=="coverage_insufficient","entire query min/max, not mean RPM, must lie within reference coverage");
    auto severity=sample(1,12);severity.windows[0].features.fill(3.);multi.push_back(severity);const auto degrees=fit_reference_model(multi);check(infer_candidate(severity.windows[0],degrees).classification=="imbalance","a separately acquired damage degree is retained as a distinct exemplar");check(infer_candidate(severity.windows[0],degrees).reference_replay,"same source hash is marked reference replay");auto independent=severity.windows[0];independent.capture_sha256=hash("independent-unknown");independent.source_session_id="new-independent-session";check(!infer_candidate(independent,degrees).reference_replay,"new unknown source is not marked as reference replay");
    auto query=s[0].windows[0];query.setup_id="other-mount";check(infer_candidate(query,m).status=="configuration_mismatch","installation guard remains active");query=s[0].windows[0];query.rpm_max=1500;const auto outside=infer_candidate(query,m);check(outside.status=="outside_operating_range","query speed guard remains active");check(std::find(outside.reasons.begin(),outside.reasons.end(),"speed_outside_reference_coverage")!=outside.reasons.end()&&std::find(outside.reasons.begin(),outside.reasons.end(),"speed_outside_normal_training_domain")==outside.reasons.end(),"four-class speed rejection refers to reference coverage, not a normal training domain");query=s[0].windows[0];query.valid=false;query.reasons={"input_integrity_unverified"};check(infer_candidate(query,m).status=="quality_gated","query integrity gate remains active");query=s[0].windows[0];query.synthetic=true;check(infer_candidate(query,m).status=="quality_gated","synthetic flag cannot be overridden by a supplied valid flag");
    std::vector<ReferenceSample>large;for(unsigned i=0;i<100;++i){auto one=sample(i%4,100+i);for(unsigned j=0;j<36;++j)one.windows[0].features[j]+=.000123456789*i+.00123456789*j;large.push_back(one);}const auto big=fit_reference_model(large);const auto text=candidate_model_text(big);check(text.size()>65536&&parse_candidate_model(text).references.size()==100,"multi-condition model larger than old 64KiB limit reloads exactly");auto badSession=big;badSession.references[1].session_id=badSession.references[0].session_id;rejects([&]{candidate_model_text(badSession);},"imported model cannot turn two segments of one session into distinct sources");
    std::cout<<"PASS: mathematical feature fixtures only; multi-RPM and multi-degree file-balanced reference matching, unknown/config/RPM/quality rejection, duplicate/session protection, provenance persistence. No independent machine accuracy measured.\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
